<script setup lang="ts">
import{ref}from'vue';import{generateCommunication,type CommunicationType}from'@/api/communication'
const resumeVersionId=ref('');const jobId=ref('');const type=ref<CommunicationType>('COVER_LETTER');const draft=ref('');const error=ref('');const loading=ref(false)
async function generate(){loading.value=true;error.value='';try{draft.value=(await generateCommunication(Number(resumeVersionId.value),Number(jobId.value),type.value)).data.data.draft}catch{error.value='生成失败，请确认 AI 授权和资源归属。'}finally{loading.value=false}}
</script>
<template><section class="workspace-page"><p class="eyebrow">Communication drafts</p><h1>求职沟通文案</h1><p>系统只生成可编辑草稿，不会自动发送或联系招聘方。</p><form class="workspace-card compact-form" @submit.prevent="generate"><label>简历版本 ID<input v-model="resumeVersionId" inputmode="numeric" /></label><label>JD ID<input v-model="jobId" inputmode="numeric" /></label><label>文案类型<select v-model="type"><option value="COVER_LETTER">求职信</option><option value="EMAIL">邮件正文</option><option value="OPENING_MESSAGE">平台开场白</option></select></label><button class="btn-neon btn-primary" :disabled="loading">{{loading?'生成中…':'生成草稿'}}</button></form><p v-if="error" class="form-error">{{error}}</p><article v-if="draft" class="workspace-card"><p class="disclaimer">请人工检查事实后再复制使用。</p><label>可编辑草稿<textarea v-model="draft" rows="14" /></label></article></section></template>
